// This function generates a sarcastic response based on the input message.
function generateSarcasticResponse(message) {
    // Convert the message to lowercase for uniformity
    const lowerCaseMessage = message.toLowerCase();

    // Define some common phrases that can be used sarcastically
    const sarcasticPhrases = [
        Oh, really?,
        Wow, I had no idea!,
        You don't say!,
        That's just amazing!,
        I'm so impressed!
    ];

    // Randomly select a sarcastic phrase
    const randomIndex = Math.floor(Math.random() * sarcasticPhrases.length);
    const selectedPhrase = sarcasticPhrases[randomIndex];

    // Return the sarcastic response
    return `${selectedPhrase} ${lowerCaseMessage}`;
}

// Example usage
const userMessage = I just found out that the sky is blue.;
const response = generateSarcasticResponse(userMessage);
console.log(response);
```

